def lcs_length(a, b):
    # table[i][j]: the answer for the first i characters of a and the first j characters of b
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1          # the two last characters match: extend
            else:
                table[i][j] = max(table[i - 1][j], table[i][j - 1])   # drop the last character of one of them
    return table[len(a)][len(b)]
